const input = $input.first().json;
const event = (input && typeof input.body === 'object' && input.body !== null) ? input.body : input;
const chatId = String($('Config').first().json.TELEGRAM_SUPPORT_CHAT_ID ?? '').trim();
if (!chatId || chatId === '<TELEGRAM_SUPPORT_CHAT_ID>') {
  throw new Error('TELEGRAM_SUPPORT_CHAT_ID não configurado no nó Config.');
}
const eventId = typeof event?.event_id === 'string' ? event.event_id.trim() : '';
const state = $getWorkflowStaticData('global');
const seen = Array.isArray(state.seenEventIds) ? state.seenEventIds : [];
if (eventId && seen.includes(eventId)) {
  return [];
}
return [{ json: { event, eventId, chatId } }];

const { event, eventId, chatId } = $input.first().json;
const escapeMdV2 = (v) => String(v ?? '').replace(/([\\_*\[\]()~`>#+\-=|{}.!])/g, '\\$1');
const escapeCode = (v) => String(v ?? '').replace(/([\\`])/g, '\\$1');
const safeSliceEscaped = (str, maxLen) => {
  if (maxLen <= 0) return '';
  if (str.length <= maxLen) return str;
  let sliced = str.slice(0, maxLen);
  let backslashes = 0;
  for (let i = sliced.length - 1; i >= 0 && sliced[i] === '\\'; i--) {
    backslashes++;
  }
  if (backslashes % 2 === 1) {
    sliced = sliced.slice(0, -1);
  }
  return sliced;
};
const isTest = event?.is_test === true;
const title = isTest ? '\\[TESTE\\] 🚨 *Falha no Guia do Turista*' : '🚨 *Falha no Guia do Turista*';
const environment = event?.environment ?? 'desconhecido';
const method = event?.request?.method ?? 'N/A';
const route = event?.request?.route ?? 'N/A';
const statusCode = event?.request?.status_code ?? 'N/A';
const errorType = event?.error?.type ?? 'ErroDesconhecido';
const errorMessage = String(event?.error?.message ?? '');
const stackTrace = String(event?.error?.stack_trace ?? '').trim();
const traceId = String(event?.trace_id ?? 'sem-trace-id');
const occurredAt = String(event?.occurred_at ?? new Date().toISOString());
const buildHeader = (msgEscaped) => [
  title,
  `*Ambiente:* ${escapeMdV2(environment)}`,
  `*Rota:* \`${escapeCode(`${method} ${route}`)}\` \\| *Status:* ${escapeMdV2(statusCode)}`,
  `*Erro:* ${escapeMdV2(errorType)}`,
  `*Mensagem:* ${msgEscaped}`,
  `*Trace ID:* \`${escapeCode(traceId)}\``,
  `*Horário:* ${escapeMdV2(occurredAt)}`,
].join('\n');
const msgEscaped = escapeMdV2(errorMessage);
let header = buildHeader(msgEscaped);
if (header.length > 4096) {
  const emptyHeader = buildHeader('');
  const ellipsis = '\\.\\.\\.';
  const availMsg = Math.max(0, 4096 - emptyHeader.length - ellipsis.length);
  header = buildHeader(availMsg > 0 ? safeSliceEscaped(msgEscaped, availMsg) + ellipsis : '');
  if (header.length > 4096) {
    header = safeSliceEscaped(header, 4096);
  }
}
let text = header;
if (stackTrace) {
  const prefix = '\n\n*Stack trace:*\n```\n';
  const suffix = '\n```';
  const truncSuffix = '\n... (truncado)';
  const stackEscaped = escapeCode(stackTrace);
  const remaining = 4096 - header.length;
  const fullBlock = `${prefix}${stackEscaped}${suffix}`;
  if (fullBlock.length <= remaining) {
    text = `${header}${fullBlock}`;
  } else {
    const maxContent = remaining - prefix.length - truncSuffix.length - suffix.length;
    if (maxContent >= 40) {
      const cutStack = safeSliceEscaped(stackEscaped, maxContent);
      text = `${header}${prefix}${cutStack}${truncSuffix}${suffix}`;
    }
  }
}
if (text.length > 4096) {
  text = safeSliceEscaped(text, 4096);
}
return [{ json: { chatId, eventId, text } }];

const { eventId } = $('Formatar alerta MarkdownV2').first().json;
const state = $getWorkflowStaticData('global');
if (eventId) {
  const seen = Array.isArray(state.seenEventIds) ? state.seenEventIds : [];
  state.seenEventIds = [...seen.filter((id) => id !== eventId), eventId].slice(-50);
}
return [{ json: { alerted: true, event_id: eventId } }];
